[{"id":"regiment1-0","name":"1st (Alum) Regiment","legend":"Regiment was formed in 1794 Standenby Era during the Madramian Rebellion. 1st (Alum) Regiment is stationed in Atetum. \r\n\r\nRegiment composition in 1836 SE:\r\n— infantry: 3013\r\n— cavalry: 1304\r\n— artillery: 46\r\n— archers: 1770."},{"id":"regiment1-1","name":"2nd (Pargocobri) Regiment","legend":"Regiment was formed in 1602 Standenby Era during the Ausus Campaign. 2nd (Pargocobri) Regiment is stationed in Pollum. \r\n\r\nRegiment composition in 1836 SE:\r\n— infantry: 1521\r\n— cavalry: 683\r\n— artillery: 17\r\n— archers: 805."},{"id":"regiment1-2","name":"3rd (Murnoduri) Regiment","legend":"Regiment was formed in 1834 Standenby Era during the Lutumian Campaign. 3rd (Murnoduri) Regiment is stationed in Murnoduri. \r\n\r\nRegiment composition in 1836 SE:\r\n— archers: 813\r\n— cavalry: 285\r\n— artillery: 28\r\n— infantry: 935."},{"id":"regiment1-3","name":"1st Fleet","legend":"Regiment was formed in 1830 Standenby Era during the Lutumian Campaign. 1st Fleet is based in Murnoduri. \r\n\r\nRegiment composition in 1836 SE:\r\n— fleet: 7."},{"id":"regiment3-0","name":"1st (Phalolyntia) Regiment","legend":"Regiment was formed in 1796 Standenby Era during the Iburgenian Campaign. 1st (Phalolyntia) Regiment is stationed in Pegalia. \r\n\r\nRegiment composition in 1836 SE:\r\n— archers: 1504\r\n— cavalry: 1032\r\n— infantry: 1793\r\n— artillery: 152."},{"id":"regiment3-1","name":"2nd (Susis) Regiment","legend":"Regiment was formed in 1793 Standenby Era during the Iburgenian Campaign. 2nd (Susis) Regiment is stationed in Susis County. \r\n\r\nRegiment composition in 1836 SE:\r\n— infantry: 1208\r\n— cavalry: 789\r\n— archers: 566\r\n— artillery: 39."},{"id":"regiment3-2","name":"1st Fleet","legend":"Regiment was formed in 1835 Standenby Era during the Oceatisan Campaign. 1st Fleet is based in Pegalia. \r\n\r\nRegiment composition in 1836 SE:\r\n— fleet: 60."},{"id":"regiment4-0","name":"1st (Fanha) Regiment",